(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(x,d=0)=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(x));
const pct=x=>nf(x*100,3)+'%';
const labels={secilen_sistem:'Doğrulamayla seçilen sistem',flaml_automl:'FLAML adayı',
  lightgbm__hareketli:'Manuel LightGBM',random_forest__hareketli:'Manuel Random Forest',catboost__hareketli:'Manuel CatBoost',
  ay_sonu_koru:'Ay sonu stokunu koru',son_ayi_koru:'Son ay ortalamasını koru',egitim_ortalamasi:'Eğitim ortalaması'};
const learners={lgbm:'LightGBM',rf:'Random Forest',catboost:'CatBoost'};
const groupNames={UC_BUYUK_IL:'İstanbul / Ankara / İzmir',DIGER_ILLER:'Diğer iller',ALL:'Tüm şubeler'};
const colors={flaml_automl:'#557ca4',secilen_sistem:'#318975',ay_sonu_koru:'#6e7886',son_ayi_koru:'#a1aab4'};
function score(data,state,model){return (state.group==='ALL'?data.total_metrics:data.metrics).find(r=>r.gosterge===state.target&&r.model===model&&r.split===state.split&&(state.group==='ALL'||r.sube_grubu===state.group));}
function trace(data,meta){
 const rows=data.search_updates.filter(r=>r.gosterge===meta.target&&r.sube_grubu===meta.group);
 if(!rows.length)return '<p>Arama eğrisi bulunamadı.</p>';
 const W=650,H=245,L=65,R=20,T=20,B=38;
 const min=Math.min(...rows.map(r=>r.en_iyi_valid_wape))*.97,max=Math.max(...rows.map(r=>r.en_iyi_valid_wape))*1.04;
 const duration=meta.search_budget_seconds,xx=t=>L+(W-L-R)*Math.min(t/duration,1),yy=v=>T+(H-T-B)*(1-(v-min)/(max-min||1));
 return `<svg class="flaml-trace" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(groupNames[meta.group])} doğrulama arama eğrisi">${[0,.5,1].map(t=>{const v=min+(max-min)*t;return `<line x1="${L}" x2="${W-R}" y1="${yy(v)}" y2="${yy(v)}" stroke="#e8edf1"/><text x="${L-8}" y="${yy(v)+4}" text-anchor="end" font-size="13" fill="#6d7e8d">${pct(v)}</text>`;}).join('')}${[0,.25,.5,.75,1].map(t=>`<text x="${xx(duration*t)}" y="${H-10}" text-anchor="middle" font-size="13" fill="#6d7e8d">${nf(duration*t)} sn</text>`).join('')}<polyline points="${rows.map(r=>`${xx(r.arama_saniye)},${yy(r.en_iyi_valid_wape)}`).join(' ')}" fill="none" stroke="#557ca4" stroke-width="2.5"/>${rows.map(r=>`<circle cx="${xx(r.arama_saniye)}" cy="${yy(r.en_iyi_valid_wape)}" r="2.5" fill="#557ca4"><title>${learners[r.algoritma]} · ${nf(r.arama_saniye,1)} sn · doğrulama WAPE ${pct(r.en_iyi_valid_wape)}</title></circle>`).join('')}</svg>`;
}
window.renderFlamlPage=(data,state)=>{
 if(!data)return '<section class="card"><div class="card-body">FLAML çalışmasının doğrulanmış çıktısı henüz yüklenmedi.</div></section>';
 const groups=state.group==='ALL'?['UC_BUYUK_IL','DIGER_ILLER']:[state.group];
 const meta=data.model_metadata.filter(m=>m.target===state.target&&groups.includes(m.group));
 const records=Object.entries(labels).map(([key,label])=>({key,label,score:score(data,state,key)}));
 const best=Math.min(...records.map(r=>r.score.wape));
 const bars=['secilen_sistem','flaml_automl','ay_sonu_koru','son_ayi_koru'];
 const max=Math.max(...bars.map(key=>score(data,state,key).wape))*1.1;
 const info=data.manifest;
 const common=data.global_selection;
 const sharedName=common?learners[common.selected_learner]:null;
 const globalPanel=common?`<section class="card space-bottom"><div class="card-head"><div><h2>Bütün göstergelerde ortak algoritma: ${sharedName}</h2><p>Üç göstergenin banka geneli doğrulama WAPE ortalaması eşit ağırlıklıdır. En düşük hata seçilir; gösterge ve şube grubu algoritmayı değiştirmez.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Algoritma</th><th class="num">TL vadesiz</th><th class="num">TL vadeli</th><th class="num">Kredi</th><th class="num">Ortalama WAPE</th></tr></thead><tbody>${common.algorithm_scores.map(r=>`<tr><td>${learners[r.learner]}${r.learner===common.selected_learner?'<span class="badge-best">Ortak seçim</span>':''}</td>${['tl_vadesiz','tl_vadeli','kredi'].map(t=>`<td class="num">${pct(r.indicator_wape[t])}</td>`).join('')}<td class="num">${pct(r.mean_indicator_wape)}</td></tr>`).join('')}</tbody></table></div><div class="card-body"><p>Tek algoritma ailesi kullanılır. Gösterge ve şube grubu için ayrı eğitim/parametre seti vardır; tek bir çok çıktılı model nesnesi değildir. Referanslar yalnızca karşılaştırma içindir.</p></div></section>`:'';
 return `<div class="flaml-page"><div class="flaml-intro"><div><span class="badge model">V4 · 49 alan · ${info.searches} arama</span><p>${common?`Önceki ${nf(info.trial_count)} FLAML denemesi yeniden kullanıldı. Tüm göstergeler ve şube grupları için tek algoritma seçildi: <b>${sharedName}</b>.`:`Arama başına ${nf(info.settings.time_budget_per_search)} sn hedef bütçe, 2 CPU iş parçacığı. Toplam ${nf(info.trial_count)} deneme tamamlandı.`}</p></div><a class="button secondary" href="downloads/flaml_metodoloji.md" download>Metodolojiyi indir</a></div>${globalPanel}<div class="metric-strip">${[['Seçilen sistem',score(data,state,'secilen_sistem')],['FLAML adayı',score(data,state,'flaml_automl')],['Ay sonu referansı',score(data,state,'ay_sonu_koru')]].map(([label,r])=>`<div class="metric-cell"><small>${label} · WAPE</small><strong>${pct(r.wape)}</strong><div class="metric-desc">${nf(r.n)} şube-ay · ${state.split==='TEST'?'tarihsel test karşılaştırması':'doğrulama'}</div></div>`).join('')}</div><section class="card space-bottom"><div class="card-head"><div><h2>Arama sonucu ve seçilen sistem</h2><p>${common?"Ortak algoritma üç göstergenin doğrulama WAPE ortalamasıyla seçildi. Seçilen sistem ile FLAML adayı aynı ortak algoritmayı kullanır.":"Her gösterge–şube grubunda seçim yalnızca doğrulama MAE ile yapıldı. Referans veya mevcut model de kazanabilir."}</p></div></div><div class="card-body">${bars.map(key=>{const r=score(data,state,key);return `<div class="comparison-row"><span class="model-label"><i class="legend-dot" style="background:${colors[key]}"></i>${key==='secilen_sistem'?'Seçilen sistem':key==='ay_sonu_koru'?'Ay sonu referansı':key==='son_ayi_koru'?'Son ay ortalaması':labels[key]}</span><div class="bar-track"><div class="bar-fill" style="width:${r.wape/max*100}%;background:${colors[key]}"></div></div><strong>${pct(r.wape)}</strong></div>`;}).join('')}</div></section><div class="group-panels">${meta.map(m=>`<section class="card"><div class="card-head"><div><h2>${groupNames[m.group]}</h2><p>${nf(m.trials)} deneme · ${nf(m.search_seconds,1)} sn arama</p></div></div><div class="card-body"><div class="flaml-selection"><small>${common?"Ortak algoritma":"Doğrulamada seçilen yöntem"}</small><strong>${common?sharedName:esc(labels[m.selected_candidate])}</strong><p>FLAML’nin kendi aday algoritması: <b>${learners[m.best_learner]}</b>. Gerçek eğitilmiş ağaç sayısı: ${nf(m.actual_trees)}.</p></div><div class="flaml-learner-counts">${Object.entries(m.trial_counts).map(([key,n])=>`<span>${learners[key]} <b>${nf(n)}</b></span>`).join('')}</div><details class="flaml-config"><summary>FLAML’nin seçtiği parametreler</summary><pre>${esc(JSON.stringify(m.best_config,null,2))}</pre></details></div></section>`).join('')}</div><section class="card space-bottom"><div class="card-head"><div><h2>Aynı V4 satırlarında karşılaştırma</h2><p>${esc(groupNames[state.group])} · ${state.split==='TEST'?'Ekim–Aralık 2026':'Temmuz–Eylül 2026'} · WAPE düşük oldukça iyi</p></div><button class="button secondary small" id="export-flaml">Seçili tabloyu indir</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tahminleyici</th><th class="num">Gözlem</th><th class="num">MAE · TL</th><th class="num">RMSE · TL</th><th class="num">WAPE</th><th class="num">R²</th><th class="num">Toplam sapması</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r.label}${Math.abs(r.score.wape-best)<1e-12?'<span class="badge-best">En düşük hata</span>':''}</td><td class="num">${nf(r.score.n)}</td><td class="num">${nf(r.score.mae_tl)}</td><td class="num">${nf(r.score.rmse_tl)}</td><td class="num">${pct(r.score.wape)}</td><td class="num">${nf(r.score.r2,3)}</td><td class="num">${pct(r.score.toplam_sapma_orani)}</td></tr>`).join('')}</tbody></table></div></section><div class="group-panels">${meta.map(m=>`<section class="card"><div class="card-head"><div><h2>${groupNames[m.group]} · arama eğrisi</h2><p>${common?"Seçilen algoritmanın önceki aramalarda iyileşen doğrulama noktaları. Yeni arama yapılmadı.":"Yalnızca iyileşen doğrulama noktaları. Bu eğri test verisi kullanmaz."}</p></div></div><div class="flaml-trace-wrap">${trace(data,m)}</div></section>`).join('')}</div><p class="inline-note">Ekim–Aralık 2026 önceki çalışmada incelendi; burası yeniden kullanılan tarihsel karşılaştırmadır. Gerçek veri için ileriye dönük yeni aylarda ayrıca izleme gerekir. ${common?`Önceki arama toplamı ${nf(info.search_seconds_total,1)} sn. Ortak seçim ve yeniden eğitim ${nf(info.pipeline_seconds,1)} sn; yeni arama yapılmadı.`:`Arama toplamı ${nf(info.search_seconds_total,1)} sn; yeniden eğitim ve kayıtlar dahil koşu ${nf(info.pipeline_seconds,1)} sn.`}</p><p class="inline-note">FLAML özellik önemleri bu pilotta yeniden hesaplanmadı. Önceki V4 önemleri önceki modellerindir. Tüm denemeler <a class="link-button" href="downloads/flaml_arama_gecmisi.csv" download>arama geçmişi CSV</a> içinde bulunur.</p></div>`;
};
window.exportFlamlTable=(data,state)=>{
 const rows=[['gosterge','sube_grubu','split','model','n','mae_tl','rmse_tl','wape','r2','toplam_sapma_orani'],...Object.keys(labels).map(model=>{const r=score(data,state,model);return [state.target,state.group,state.split,model,r.n,r.mae_tl,r.rmse_tl,r.wape,r.r2,r.toplam_sapma_orani];})];
 const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');
 a.href=url;a.download=`flaml_${state.target}_${state.group}_${state.split}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);
};
})();
